use /lib
use /ui/components/sidebar/Sidebar
from /scope/application/Body import BodyScope
from /scope/prompt-mode/message-list import MessageList
from /ui/components/file-tree import FileTreeScope
from /ui/components/git-panel import GitPanelScope
from /ui/components/sidebar import SidebarScope

export sidebar ProjectSidebarScope:
    side: left

    panels:
        - @{FileTreeScope}
        - @{GitPanelScope}

    concept: {ProjectSidebarConcept}

concept ProjectSidebarConcept:
    pitch:
        The @{SidebarScope} along the left of the main window, beside the
        @{BodyScope}, holding the tools for finding your way around the
        project.

    shape: {ProjectSidebarShape}

shape ProjectSidebarShape:
    description:
        Runs the full height of the window beneath the ribbon, to the left of
        the body and the chat input beneath it. The file tree fills it from
        the top, and the git panel sits along the bottom, underneath it,
        taking only the height it needs.

    others:
        It is the only sidebar on the body's left. While a task runs, a second
        one, the running task's referenced spec, slides out at the right of
        the message list, as the @{MessageList} says.

----
use /lib
from /ui import UiComponent

// A panel in a sidebar. What it is like follows from its properties, each
// switching the text of the panel section as the panel is extended.
export abstract anchor Panel extends UiComponent as panel:
    // Its header's title, or none for a panel with no header.
    title:: null:: string: null
    // Whether its header counts what it lists.
    counted:: boolean: false
    // How it takes its height: fill, fit, or share.
    height:: string: fill
    // Whether its contents scroll within it.
    scrolls:: boolean: true

    panel:
        ${self.title != null ? "It has a header along its top, reading its title in small, semibold text, with a little padding around it. The header is on the theme's raised surface and the panel's body on its base surface, so the header stands slightly apart from the body, contrasting with it only a little, with no line between them." : "It has no header: its contents start at its top edge, on the theme's base surface."}

        ${self.counted ? "At its header's right, how many rows it lists, in smaller text, muted." : "It shows no count of what it lists."}

        ${self.height == "share" ? "It shares the height its sidebar's other panels leave with the other panels that share it, one above the other, split by a line that can be dragged to change their shares, each at least 80 pixels tall. They start with equal shares." : self.height == "fit" ? "It is only as tall as its contents need, taking no more of its sidebar's height." : "It fills the height its sidebar's other panels leave."}

        ${self.scrolls ? "Its contents scroll on their own when they are taller than it, with a permanent scrollbar along its right, as the ScrollbarScope says." : "Its contents never scroll: it is as tall as they are."}
----
6803cbe - Add theme editor to Application tab - Make git panel shrink to fit and grow to 50% height - Fix unwanted scrolling in referenced spec panels - Restyle chat input with dark box and stacked buttons - Split MessageList spec into separate addressable files - Add Body scope spec and refactor related scopes
8a03dab - Rework scrollbar styling to match mockup - Implement smooth brightness slider with gradual light-dark transition - Add Ctrl+N to start new conversation and record in anchor - Add queue reordering and per-prompt new conversation toggle - Make git panel resizable and scrollable
2b53ee5 - Add raw prompt viewer modal to task header - Hide Send button after successful task transfer - Add right-click menu to mark sent tasks as done - Mark sent tasks complete to prevent sending back - Add image attachment support to chat input - Update ribbon to match mockup - Update sidebar styling to match design mockup - Redesign right sidebar layout and styling - Update spec to document batch-send task functionality - Document Freeform tab in spec - Update raw-prompt modal spec to match implementation - Update spec for sending prompts between modes - Document mark-as-done feature for tasks - Document image attachment behavior in spec - Update file-tree and git-panel specs to match code - Spec: document right sidebar behavior and styling - Update scrollbars to match surface colors - Add brightness slider to application settings - Extend run log background under scrollbar - Replace dark mode toggle with continuous brightness slider - Update scrollbar spec to match implementation - Update spec to document brightness slider behavior - Document image drag-drop and paste in chat input spec - Update Run panel output log scrollbar spec - Fix phrase comparing brightness slider to ribbon's switches - Document brightness slider behavior in spec
7f76db8 - Add Agent setting to select Claude Code, Codex, or OpenCode - Allow new conversation during running tasks - Support sending messages to running tasks

